#[test]fn actual_supervisor_terminal_forms(){for (stop,success,code,reason) in [(Some("timeout"),true,Some(0),helper::Reason::Timeout),(Some("trace_budget_exhausted"),false,None,helper::Reason::TraceBudgetExhausted),(None,false,Some(137),helper::Reason::WorkerFailed),(None,false,None,helper::Reason::WorkerFailed),(None,true,Some(0),helper::Reason::WorkerFailed)]{let a=check(&outcome(stop,success,code));assert_eq!(a.result,Ok(helper::Envelope{reason,exit_code:code}));}}
#[test]fn generic_errors_success_and_reports_rejected(){for status in ["error","budget_exhausted","partial","verified","unsupported"]{let mut o=outcome(None,false,Some(1));o["status"]=json!(status);assert!(check(&o).result.is_err());}for k in ["adapter_id","strategy","schema","capture_snapshot_complete","capture_snapshot_index","first_stop","report_capture_join_verified"]{let mut o=outcome(None,false,Some(1));o[k]=Value::Null;assert!(check(&o).result.is_err());}}
#[test]fn missing_or_contradictory_completion_refused(){let mut o=outcome(None,false,Some(1));o.as_object_mut().unwrap().remove("solver_completed");assert!(check(&o).result.is_err());for k in ["solver_completed","scalar_recovered","scalar_recovered_without_witness","ecdlp_pipeline_completed","all_patterns_covered","all_patterns_negative","full_span_search","training_export_admitted"]{for v in [json!(true),Value::Null,json!(0),json!("false")]{let mut o=outcome(None,false,Some(1));o[k]=v;assert!(check(&o).result.is_err(),"{k}");}let mut o=outcome(None,false,Some(1));o[k]=json!(false);assert!(check(&o).result.is_ok());}}
#[test]fn degree_labels_must_be_null(){for k in ["first_fall_degree","last_fall_degree","degree_of_regularity"]{let mut o=outcome(None,false,Some(1));o[k]=json!(4);assert!(check(&o).result.is_err());o[k]=Value::Null;assert!(check(&o).result.is_ok());}}
#[test]fn disposition_exact_bounded_and_absence_sensitive(){let mut o=outcome(None,false,Some(1));o["requested_channels"]["extra"]=json!(true);assert_eq!(check(&o).result,Err(helper::Failure::Disposition));o.as_object_mut().unwrap().remove("requested_channels");assert_eq!(check(&o).result,Err(helper::Failure::Disposition));assert!(helper::verify(&o,None,helper::Limits{work:100000,depth:32},Instant::now()+Duration::from_secs(1),&mut Owner::default()).result.is_ok());o["requested_channels"]=Value::Null;assert!(helper::verify(&o,None,helper::Limits{work:100000,depth:32},Instant::now()+Duration::from_secs(1),&mut Owner::default()).result.is_err());}
#[test]fn supervisor_required_and_exact(){for k in ["exit_code","elapsed_ms_diagnostic","clock_valid_for_comparison","retired_instructions","instruction_counter_status","memory_limit_bytes","worker_output_bytes_before_seal","output_budget_bytes","output_budget_scope","checkpoint_mid_call","interrupted_trace_loss_possible"]{let mut o=outcome(None,false,Some(1));o["supervisor"].as_object_mut().unwrap().remove(k);assert!(check(&o).result.is_err());}for (k,v) in [("elapsed_ms_diagnostic",json!(-1)),("retired_instructions",json!(1)),("memory_limit_bytes",json!(-1)),("checkpoint_mid_call",json!(true)),("clock_valid_for_comparison",json!(true)),("exit_code",json!(2147483648u64)),("instruction_counter_status",json!("counted")),("interrupted_trace_loss_possible",json!(false))]{let mut o=outcome(None,false,Some(1));o["supervisor"][k]=v;assert!(check(&o).result.is_err());}}
#[test]fn exit_codes_cannot_conflict_or_claim_failed_zero(){let mut o=outcome(None,false,Some(1));o["exit_code"]=json!(2);assert_eq!(check(&o).result,Err(helper::Failure::Contradiction));let o=outcome(None,false,Some(0));assert_eq!(check(&o).result,Err(helper::Failure::Contradiction));let mut o=outcome(Some("timeout"),true,Some(0));o["exit_code"]=json!(0);assert_eq!(check(&o).result,Err(helper::Failure::Contradiction));}
#[test]fn same_owner_budget_and_postcheck_charge(){let o=outcome(None,false,Some(1));let mut owner=Owner::default();let a=helper::verify(&o,Some(&expected()),helper::Limits{work:1,depth:32},Instant::now()+Duration::from_secs(1),&mut owner);assert_eq!(a.result,Err(helper::Failure::Cap));assert_eq!(a.charged_work,owner.work);let mut owner=Owner{fail_check:Some(2),..Owner::default()};let a=helper::verify(&o,Some(&expected()),helper::Limits{work:100000,depth:32},Instant::now()+Duration::from_secs(1),&mut owner);assert_eq!(a.result,Err(helper::Failure::Owner));assert_eq!(a.charged_work,1);assert_eq!(owner.work,1);}
#[test]fn expiration_and_owner_refusal_do_not_validate(){let o=outcome(None,false,Some(1));let a=helper::verify(&o,Some(&expected()),helper::Limits{work:100000,depth:32},Instant::now(),&mut Owner::default());assert_eq!(a.result,Err(helper::Failure::Deadline));let a=helper::verify(&o,Some(&expected()),helper::Limits{work:100000,depth:32},Instant::now()+Duration::from_secs(1),&mut Owner{fail_at:Some(1),..Owner::default()});assert_eq!(a.result,Err(helper::Failure::Owner));}
#[test]fn nested_disposition_depth_is_bounded(){let mut e=json!(true);for _ in 0..70{e=json!([e]);}let mut o=outcome(None,false,Some(1));o["requested_channels"]=e.clone();let a=helper::verify(&o,Some(&e),helper::Limits{work:1000000,depth:usize::MAX},Instant::now()+Duration::from_secs(1),&mut Owner::default());assert_eq!(a.result,Err(helper::Failure::Depth));}
#[test]fn large_disposition_string_is_charged_before_comparison(){let e=json!({"large":"x".repeat(100000)});let mut o=outcome(None,false,Some(1));o["requested_channels"]=e.clone();let mut owner=Owner::default();let a=helper::verify(&o,Some(&e),helper::Limits{work:10000,depth:32},Instant::now()+Duration::from_secs(1),&mut owner);assert_eq!(a.result,Err(helper::Failure::Cap));assert!(owner.work<=10000);}
#[test]fn repeated_invocations_cannot_reset_parent_owner(){struct Bounded{spent:u64,cap:u64}impl wire::Admission for Bounded{fn reserve(&mut self,w:u64,_:u64)->Result<(),()>{let n=self.spent.checked_add(w).ok_or(())?;if n>self.cap{return Err(())}self.spent=n;Ok(())}fn check(&mut self)->Result<(),()>{Ok(())}}let o=outcome(None,false,Some(1));let exact=check(&o).charged_work;let mut owner=Bounded{spent:0,cap:exact};let deadline=Instant::now()+Duration::from_secs(1);assert!(helper::verify(&o,Some(&expected()),helper::Limits{work:100000,depth:32},deadline,&mut owner).result.is_ok());assert_eq!(helper::verify(&o,Some(&expected()),helper::Limits{work:100000,depth:32},deadline,&mut owner).result,Err(helper::Failure::Owner));assert_eq!(owner.spent,exact);}
